  const fallback = side === 'us' ? 'Us' : 'Dem';
  if (!game || (side !== 'us' && side !== 'dem')) return fallback;
  const playersField = side === 'us' ? game.usPlayers || game.usTeamPlayers || game.usTeam : game.demPlayers || game.demTeamPlayers || game.demTeam;
