function buildModelFeatureVector({ diff, roundIdx, momentum, bidAmount, biddingTeamSign, pointDelta }) {
  const safeDiff = parseFiniteNumber(diff, 0);
  const safeRoundIdx = Math.max(0, Math.trunc(parseFiniteNumber(roundIdx, 0)));
  const safeMomentum = parseFiniteNumber(momentum, 0);
  const safeBidAmount = parseFiniteNumber(bidAmount, 0);
  const safeBiddingTeamSign = parseFiniteNumber(biddingTeamSign, 0);
  const safePointDelta = parseFiniteNumber(pointDelta, 0);

  return {
    diff: safeDiff,
    round_idx: safeRoundIdx,
    momentum: safeMomentum,
    bid_amount: safeBidAmount,
    bidding_team_sign: safeBiddingTeamSign,
    point_delta: safePointDelta,
    abs_diff: Math.abs(safeDiff),
    abs_momentum: Math.abs(safeMomentum),
    diff_x_round: safeDiff * safeRoundIdx,
    point_delta_x_round: safePointDelta * safeRoundIdx,
    bid_x_team: safeBidAmount * safeBiddingTeamSign,
    diff_x_point_delta: safeDiff * safePointDelta,
    momentum_x_round: safeMomentum * safeRoundIdx,
    lead_sign: safeDiff > 0 ? 1 : safeDiff < 0 ? -1 : 0,
  };
}

function extractModelFeaturesFromRoundContext(roundIndex, lastRound, prevRound = null) {
  const safeRoundIndex = Math.max(0, Math.trunc(parseFiniteNumber(roundIndex, 0)));
  const lastTotals = sanitizeTotals(lastRound?.runningTotals);
  const prevTotals = sanitizeTotals(prevRound?.runningTotals);

  const diff = lastTotals.us - lastTotals.dem;
  const prevDiff = prevTotals.us - prevTotals.dem;
  const momentum = safeRoundIndex === 0 ? 0 : diff - prevDiff;
  const bidAmount = parseFiniteNumber(lastRound?.bidAmount, 0);
  const biddingTeamSign = getBiddingTeamSign(lastRound?.biddingTeam);
  const usPoints = parseFiniteNumber(lastRound?.usPoints, 0);
  const demPoints = parseFiniteNumber(lastRound?.demPoints, 0);
  const pointDelta = usPoints - demPoints;

  return buildModelFeatureVector({
    diff,
    roundIdx: safeRoundIndex,
    momentum,
    bidAmount,
    biddingTeamSign,
    pointDelta,
  });
}

function computeRawModelProbabilityFromFeatures(features, model = getActiveRuntimeModel()) {
  let z = parseFiniteNumber(model?.intercept, 0);
  for (const featureName of MODEL_FEATURE_SET) {
    const featureValue = parseFiniteNumber(features?.[featureName], 0);
    const coefficient = parseFiniteNumber(model?.coefficients?.[featureName], 0);
    z += coefficient * featureValue;
  }
  return safeSigmoid(z);
}

function predictBaseModelProbabilityFromFeatures(features, model = getActiveRuntimeModel()) {
  const rawProb = computeRawModelProbabilityFromFeatures(features, model);
  return applyPlattCalibration(rawProb, model?.calibration?.slope, model?.calibration?.intercept);
}

function inferWinnerSide(game) {
  const winnerRaw = typeof game?.winner === "string" ? game.winner.trim().toLowerCase() : "";
  if (winnerRaw === "us" || winnerRaw === "dem") return winnerRaw;

  const finalTotals = sanitizeTotals(game?.finalScore);
  if (finalTotals.us > finalTotals.dem) return "us";
  if (finalTotals.dem > finalTotals.us) return "dem";
  return null;
}

function normalizeGameRoundsForModeling(rounds) {
  if (!Array.isArray(rounds) || !rounds.length) return [];
  return rounds
    .map((round, idx) => ({
      round,
      roundIndex: Math.max(0, Math.trunc(parseFiniteNumber(round?.roundIndex, idx))),
      originalIndex: idx,
    }))
    .sort((a, b) => a.roundIndex - b.roundIndex || a.originalIndex - b.originalIndex);
}

function buildPersonalizationDataset(savedGames, model = getActiveRuntimeModel()) {
  const games = Array.isArray(savedGames) ? savedGames : [];
  const logits = [];
  const labels = [];
  let gameSamples = 0;

  for (const game of games) {
    const winner = inferWinnerSide(game);
    if (!winner) continue;

    const rounds = normalizeGameRoundsForModeling(game?.rounds);
    if (!rounds.length) continue;

    let previousDiff = 0;
    let hasRoundSample = false;

    rounds.forEach((entry, idx) => {
      const round = entry.round;
      if (!round?.runningTotals) return;

      const totals = sanitizeTotals(round.runningTotals);
      const diff = totals.us - totals.dem;
      const momentum = idx === 0 ? 0 : diff - previousDiff;
      previousDiff = diff;

      const bidAmount = parseFiniteNumber(round?.bidAmount, 0);
      const biddingTeamSign = getBiddingTeamSign(round?.biddingTeam);
      const usPoints = parseFiniteNumber(round?.usPoints, 0);
      const demPoints = parseFiniteNumber(round?.demPoints, 0);
      const pointDelta = usPoints - demPoints;

      const features = buildModelFeatureVector({
        diff,
        roundIdx: entry.roundIndex,
        momentum,
        bidAmount,
        biddingTeamSign,
        pointDelta,
      });
      const baseProb = predictBaseModelProbabilityFromFeatures(features, model);
      logits.push(probabilityToLogit(baseProb));
      labels.push(winner === "us" ? 1 : 0);
      hasRoundSample = true;
    });

    if (hasRoundSample) {
      gameSamples += 1;
    }
  }

  return {
    logits,
    labels,
    roundSamples: logits.length,
    gameSamples,
  };
}

function computeBinaryLogLoss(labels, probs) {
  if (!Array.isArray(labels) || !Array.isArray(probs) || !labels.length || labels.length !== probs.length) {
    return 0;
  }

  let sum = 0;
  for (let idx = 0; idx < labels.length; idx += 1) {
    const y = parseFiniteNumber(labels[idx], 0) >= 0.5 ? 1 : 0;
    const p = clampProbability(probs[idx]);
    sum += -(y * Math.log(p) + (1 - y) * Math.log(1 - p));
  }
  return sum / labels.length;
}

function fitPersonalizationCalibration(logits, labels, options = {}) {
  const xs = Array.isArray(logits) ? logits.map(v => parseFiniteNumber(v, 0)) : [];
  const ys = Array.isArray(labels) ? labels.map(v => (parseFiniteNumber(v, 0) >= 0.5 ? 1 : 0)) : [];

  if (!xs.length || xs.length !== ys.length) {
    return {
      slope: 1,
      intercept: 0,
      baseLogLoss: 0,
      personalizedLogLoss: 0,
      accepted: false,
      improvement: 0,
      guardrailsOk: false,
    };
  }

  const lr = parseFiniteNumber(options.learningRate, PERSONALIZATION_LR);
  const epochs = Math.max(1, Math.trunc(parseFiniteNumber(options.epochs, PERSONALIZATION_EPOCHS)));
  const l2 = Math.max(0, parseFiniteNumber(options.l2, PERSONALIZATION_L2));
  const minImprovement = parseFiniteNumber(options.minImprovement, PERSONALIZATION_MIN_IMPROVEMENT);
  const minSlope = parseFiniteNumber(options.minSlope, PERSONALIZATION_MIN_SLOPE);
  const maxSlope = parseFiniteNumber(options.maxSlope, PERSONALIZATION_MAX_SLOPE);
  const maxAbsIntercept = parseFiniteNumber(options.maxAbsIntercept, PERSONALIZATION_MAX_ABS_INTERCEPT);

  let slope = 1;
  let intercept = 0;
  const n = xs.length;

  for (let epoch = 0; epoch < epochs; epoch += 1) {
    let gradSlope = 0;
    let gradIntercept = 0;

    for (let idx = 0; idx < n; idx += 1) {
      const z = slope * xs[idx] + intercept;
      const p = safeSigmoid(z);
      const err = p - ys[idx];
      gradSlope += err * xs[idx];
      gradIntercept += err;
    }

    gradSlope = (gradSlope / n) + (l2 * slope);
    gradIntercept /= n;

    slope -= lr * gradSlope;
    intercept -= lr * gradIntercept;
  }

  const baseProbs = xs.map(v => safeSigmoid(v));
  const personalizedProbs = xs.map(v => safeSigmoid(slope * v + intercept));
  const baseLogLoss = computeBinaryLogLoss(ys, baseProbs);
  const personalizedLogLoss = computeBinaryLogLoss(ys, personalizedProbs);
  const improvement = baseLogLoss - personalizedLogLoss;
  const guardrailsOk = Number.isFinite(slope) && Number.isFinite(intercept)
    && slope >= minSlope && slope <= maxSlope
    && Math.abs(intercept) <= maxAbsIntercept;
  const accepted = guardrailsOk && improvement >= minImprovement;

  return {
    slope: accepted ? slope : 1,
    intercept: accepted ? intercept : 0,
    baseLogLoss,
    personalizedLogLoss: accepted ? personalizedLogLoss : baseLogLoss,
    accepted,
    improvement,
    guardrailsOk,
  };
}

function normalizePersonalizationRecord(raw) {
  if (!raw || typeof raw !== "object") return null;
  if (Number(raw.schemaVersion) !== PROBABILITY_PERSONALIZATION_SCHEMA_VERSION) return null;

  const modelId = typeof raw.modelId === "string" ? raw.modelId.trim() : "";
  if (!modelId) return null;

  const slope = parseFiniteNumber(raw.slope, NaN);
  const intercept = parseFiniteNumber(raw.intercept, NaN);
  const roundSamples = Math.max(0, Math.trunc(parseFiniteNumber(raw.roundSamples, NaN)));
  const gameSamples = Math.max(0, Math.trunc(parseFiniteNumber(raw.gameSamples, NaN)));
  const baseLogLoss = parseFiniteNumber(raw.baseLogLoss, NaN);
  const personalizedLogLoss = parseFiniteNumber(raw.personalizedLogLoss, NaN);
  const gamesHash = typeof raw.gamesHash === "string" ? raw.gamesHash : "0";
  const updatedAt = typeof raw.updatedAt === "string" ? raw.updatedAt : null;

  if (!Number.isFinite(slope) || !Number.isFinite(intercept)
      || !Number.isFinite(roundSamples) || !Number.isFinite(gameSamples)
      || !Number.isFinite(baseLogLoss) || !Number.isFinite(personalizedLogLoss)) {
    return null;
  }

  return {
    schemaVersion: PROBABILITY_PERSONALIZATION_SCHEMA_VERSION,
    modelId,
    slope,
    intercept,
    roundSamples,
    gameSamples,
    gamesHash,
    updatedAt,
    baseLogLoss,
    personalizedLogLoss,
  };
}

function isPersonalizationRecordActive(record, modelId = getActiveRuntimeModel().modelId) {
  if (!record || record.modelId !== modelId) return false;
  if (record.gameSamples < PERSONALIZATION_MIN_GAMES) return false;
  if (record.roundSamples < PERSONALIZATION_MIN_ROUNDS) return false;
  if (!(record.personalizedLogLoss <= (record.baseLogLoss - PERSONALIZATION_MIN_IMPROVEMENT))) return false;
  if (record.slope < PERSONALIZATION_MIN_SLOPE || record.slope > PERSONALIZATION_MAX_SLOPE) return false;
  if (Math.abs(record.intercept) > PERSONALIZATION_MAX_ABS_INTERCEPT) return false;
  return true;
}

function getPersonalizationSignature(record, modelId = getActiveRuntimeModel().modelId) {
  const normalized = normalizePersonalizationRecord(record);
  if (!normalized || normalized.modelId !== modelId) return "none";
  return [
    normalized.modelId,
    normalized.slope.toFixed(6),
    normalized.intercept.toFixed(6),
    normalized.roundSamples,
    normalized.gameSamples,
    normalized.gamesHash,
  ].join("|");
}

function createPersonalizationRecord(historicalGames, model = getActiveRuntimeModel(), gamesHash = getProbabilityCacheKey(historicalGames)) {
  const dataset = buildPersonalizationDataset(historicalGames, model);
  const hasEnoughData = dataset.gameSamples >= PERSONALIZATION_MIN_GAMES && dataset.roundSamples >= PERSONALIZATION_MIN_ROUNDS;
  if (!hasEnoughData) {
    return createNeutralPersonalizationRecord(model, gamesHash, dataset);
  }

  const fitResult = fitPersonalizationCalibration(dataset.logits, dataset.labels);
  const usePersonalization = hasEnoughData && fitResult.accepted;

  return {
    schemaVersion: PROBABILITY_PERSONALIZATION_SCHEMA_VERSION,
    modelId: model.modelId,
    slope: usePersonalization ? fitResult.slope : 1,
    intercept: usePersonalization ? fitResult.intercept : 0,
    roundSamples: dataset.roundSamples,
    gameSamples: dataset.gameSamples,
    gamesHash,
    updatedAt: new Date().toISOString(),
    baseLogLoss: fitResult.baseLogLoss,
    personalizedLogLoss: usePersonalization ? fitResult.personalizedLogLoss : fitResult.baseLogLoss,
  };
}

function ensureProbabilityPersonalizationForGames(historicalGames, model = getActiveRuntimeModel(), options = {}) {
  const games = Array.isArray(historicalGames) ? historicalGames : [];
  const gamesHash = getProbabilityCacheKey(games);
  const cacheKey = `${model.modelId}|${gamesHash}`;
  const force = !!options.force;

  if (!force && PERSONALIZATION_STATE_CACHE.key === cacheKey && PERSONALIZATION_STATE_CACHE.value) {
    return PERSONALIZATION_STATE_CACHE.value;
  }

  const storedRecord = normalizePersonalizationRecord(getLocalStorage(PROBABILITY_PERSONALIZATION_KEY, null));
  if (!force && storedRecord && storedRecord.modelId === model.modelId && storedRecord.gamesHash === gamesHash) {
    PERSONALIZATION_STATE_CACHE.key = cacheKey;
    PERSONALIZATION_STATE_CACHE.value = storedRecord;
    return storedRecord;
  }

  const nextRecord = createPersonalizationRecord(games, model, gamesHash);
  setLocalStorage(PROBABILITY_PERSONALIZATION_KEY, nextRecord);
  PERSONALIZATION_STATE_CACHE.key = cacheKey;
  PERSONALIZATION_STATE_CACHE.value = nextRecord;
  clearWinProbabilityCache();
  return nextRecord;
}

function refreshProbabilityPersonalizationFromSavedGames(savedGames = getLocalStorage("savedGames", []), options = {}) {
  return ensureProbabilityPersonalizationForGames(savedGames, getActiveRuntimeModel(), options);
}

function scheduleProbabilityPersonalizationRefresh(savedGames = getLocalStorage("savedGames", []), options = {}) {
  pendingPersonalizationRefresh = {
    savedGames,
    options: {
      ...(pendingPersonalizationRefresh?.options || {}),
      ...options,
      force: !!(pendingPersonalizationRefresh?.options?.force || options.force),
    },
  };
  if (pendingPersonalizationRefreshHandle !== null) return;
  pendingPersonalizationRefreshHandle = scheduleIdleWork(() => {
    const job = pendingPersonalizationRefresh || { savedGames, options };
    pendingPersonalizationRefreshHandle = null;
    pendingPersonalizationRefresh = null;
    refreshProbabilityPersonalizationFromSavedGames(job.savedGames, job.options);
  });
}

function getProbabilityContext(historicalGames, options = {}) {
  const model = getActiveRuntimeModel();
  const personalization = ensureProbabilityPersonalizationForGames(historicalGames, model, options);
  return { model, personalization };
}

function getModelProbabilitySnapshotForState(currentState, model = getActiveRuntimeModel(), personalization = null) {
  const rounds = Array.isArray(currentState?.rounds) ? currentState.rounds : [];
  if (!rounds.length) {
    return {
      modelId: model.modelId,
      features: null,
      roundIndex: 0,
      currentDiff: 0,
      momentum: 0,
      rawModelProbUs: 0.5,
      baseModelProbUs: 0.5,
      modelProbUs: 0.5,
      personalizationRecord: personalization,
      personalizationActive: false,
    };
  }

  const roundIndex = rounds.length - 1;
  const lastRound = rounds[roundIndex];
  const prevRound = roundIndex > 0 ? rounds[roundIndex - 1] : null;
  const features = extractModelFeaturesFromRoundContext(roundIndex, lastRound, prevRound);
  const rawModelProbUs = computeRawModelProbabilityFromFeatures(features, model);
  const baseModelProbUs = applyPlattCalibration(rawModelProbUs, model.calibration.slope, model.calibration.intercept);
  const personalizationRecord = normalizePersonalizationRecord(personalization);
  const personalizationActive = isPersonalizationRecordActive(personalizationRecord, model.modelId);
  const modelProbUs = personalizationActive
    ? applyPlattCalibration(baseModelProbUs, personalizationRecord.slope, personalizationRecord.intercept)
    : baseModelProbUs;

  return {
    modelId: model.modelId,
    features,
    roundIndex,
    currentDiff: features.diff,
    momentum: features.momentum,
    rawModelProbUs,
    baseModelProbUs,
    modelProbUs,
    personalizationRecord,
    personalizationActive,
  };
}

function bucketScore(diff) {
  const value = parseFiniteNumber(diff, 0);
  if (value === 0) return 0;
  const sign = value < 0 ? -1 : 1;
  const band = Math.min(Math.ceil(Math.abs(value) / 20) * 20, 180);
  return sign * band;
}

function getProbabilityCacheKey(historicalGames) {
  if (!Array.isArray(historicalGames) || !historicalGames.length) return '0';
  if (PROBABILITY_GAMES_HASH_CACHE) {
    const cachedHash = PROBABILITY_GAMES_HASH_CACHE.get(historicalGames);
    if (cachedHash) return cachedHash;
  }

  let hash = 2166136261;

  const hashText = (value) => {
    const str = String(value ?? "");
    for (let idx = 0; idx < str.length; idx += 1) {
      hash ^= str.charCodeAt(idx);
      hash = Math.imul(hash, 16777619);
    }
  };

  for (const game of historicalGames) {
    const winner = inferWinnerSide(game) || "none";
    const totals = sanitizeTotals(game?.finalScore);
    const rounds = Array.isArray(game?.rounds) ? game.rounds : [];

    hashText(game?.id || game?.timestamp || "game");
    hashText(winner);
    hashText(totals.us);
    hashText(totals.dem);
    hashText(rounds.length);

    for (let roundIdx = 0; roundIdx < rounds.length; roundIdx += 1) {
      const round = rounds[roundIdx];
      const runningTotals = sanitizeTotals(round?.runningTotals);
      hashText(roundIdx);
      hashText(round?.roundIndex ?? "");
      hashText(round?.biddingTeam || "");
      hashText(parseFiniteNumber(round?.bidAmount, 0));
      hashText(parseFiniteNumber(round?.usPoints, 0));
      hashText(parseFiniteNumber(round?.demPoints, 0));
      hashText(runningTotals.us);
      hashText(runningTotals.dem);
    }
  }

  const cacheKey = `${historicalGames.length}|${(hash >>> 0).toString(16)}`;
  if (PROBABILITY_GAMES_HASH_CACHE) {
    PROBABILITY_GAMES_HASH_CACHE.set(historicalGames, cacheKey);
  }
  return cacheKey;
}

function buildProbabilityIndex(historicalGames) {
  const table = {};
  if (!Array.isArray(historicalGames) || !historicalGames.length) return table;

  const add = (k, winner, weight) => {
    if (!table[k]) table[k] = { us: 1, dem: 1 };      // Laplace prior (1|1)
    table[k][winner] += weight;
  };

  historicalGames.forEach(g => {
    if (!g || !Array.isArray(g.rounds) || !g.rounds.length || !g.finalScore) return;

    const finalTotals = sanitizeTotals(g.finalScore);
    const winner = inferWinnerSide(g);
    const winners = winner ? [winner] : (finalTotals.us === finalTotals.dem ? ['us', 'dem'] : []);
    if (!winners.length) return;
    const weightEach = winners.length === 2 ? 0.5 : 1;

    g.rounds.forEach((r, idx) => {
      if (!r?.runningTotals) return;
      const runningTotals = sanitizeTotals(r.runningTotals);
      const diff = runningTotals.us - runningTotals.dem;
      const key = `${idx}|${bucketScore(diff)}`;
      winners.forEach(winner => add(key, winner, weightEach));
    });
  });
  return table;
}

/**
 * Calculates win probability by blending historical empirical data
 * with the calibrated regression model probability.
 */
function calculateWinProbabilityComplex(state, historicalGames, probabilityContext = null) {
  const rounds = Array.isArray(state?.rounds) ? state.rounds : [];
  if (!rounds.length) return { us: 50, dem: 50 };

  const lastRound = rounds[rounds.length - 1];
  const roundIndex = rounds.length - 1;
  const lastTotals = sanitizeTotals(lastRound?.runningTotals);
  const currentDiff = lastTotals.us - lastTotals.dem;

  const games = Array.isArray(historicalGames) ? historicalGames : [];
  const probCacheKey = getProbabilityCacheKey(games);
  if (!PROB_CACHE.has(probCacheKey)) {
    PROB_CACHE.set(probCacheKey, buildProbabilityIndex(games));
  }
  const table = PROB_CACHE.get(probCacheKey);

  const empiricalKey = `${roundIndex}|${bucketScore(currentDiff)}`;
  const counts = table[empiricalKey] || { us: 1, dem: 1 };
  const empiricalProbUs = counts.us / (counts.us + counts.dem);
  const observationsInBucket = (counts.us - 1) + (counts.dem - 1);

  const context = probabilityContext || { model: getActiveRuntimeModel(), personalization: null };
  const modelSnapshot = getModelProbabilitySnapshotForState(state, context.model, context.personalization);
  const modelProbUs = modelSnapshot.modelProbUs;

  const K_CONFIDENCE_THRESHOLD = 30;
  const beta = Math.min(1, Math.log(observationsInBucket + 1) / Math.log(K_CONFIDENCE_THRESHOLD + 1));
  const blendedProbUs = (beta * empiricalProbUs) + ((1 - beta) * modelProbUs);

  return toDisplayProbabilityPercents(blendedProbUs);
}

function calculateWinProbability(state, historicalGames, probabilityContext = null) {
  return calculateWinProbabilityComplex(state, historicalGames, probabilityContext);
}

function buildWinProbabilityCacheKey(currentState, historicalGames, probabilityContext = null) {
  const rounds = Array.isArray(currentState?.rounds) ? currentState.rounds : [];
  const lastRound = rounds[rounds.length - 1];
  const prevRound = rounds.length > 1 ? rounds[rounds.length - 2] : null;
  const lastTotals = sanitizeTotals(lastRound?.runningTotals);
  const prevTotals = sanitizeTotals(prevRound?.runningTotals);
  const roundIndex = rounds.length > 0 ? rounds.length - 1 : 0;
  const features = extractModelFeaturesFromRoundContext(roundIndex, lastRound, prevRound);
  const featureSignature = MODEL_FEATURE_SET.map(name => parseFiniteNumber(features[name], 0)).join(",");
  const gamesKey = getProbabilityCacheKey(historicalGames);
  const context = probabilityContext || getProbabilityContext(historicalGames);
  const modelId = context.model?.modelId || getActiveRuntimeModel().modelId;
  const personalizationSignature = getPersonalizationSignature(context.personalization, modelId);

  return [
    rounds.length,
    lastTotals.us,
    lastTotals.dem,
    prevTotals.us,
    prevTotals.dem,
    featureSignature,
    gamesKey,
    modelId,
    personalizationSignature,
  ].join("|");
}

function getWinProbability(currentState, historicalGames, probabilityContext = null) {
  const games = Array.isArray(historicalGames) ? historicalGames : [];
  const context = probabilityContext || getProbabilityContext(games);
  const cacheKey = buildWinProbabilityCacheKey(currentState, games, context);
  if (WIN_PROB_CACHE.key === cacheKey && WIN_PROB_CACHE.value) {
    return WIN_PROB_CACHE.value;
  }

  const value = calculateWinProbability(currentState, games, context);
  WIN_PROB_CACHE.key = cacheKey;
  WIN_PROB_CACHE.value = value;
  return value;
}

// ---- js/modules/03-storage-icons-presets.js ----
"use strict";

// --- Local Storage & Sync ---
function setLocalStorage(key, value) {
  try {
    const serialized = JSON.stringify(value);
    localStorage.setItem(key, serialized);
    LOCAL_STORAGE_CACHE.set(key, { raw: serialized, parsed: value });
    if (key === "savedGames") {
      if (typeof invalidateProbabilityCachesForGames === "function") invalidateProbabilityCachesForGames(value);
      if (typeof clearStatisticsCache === "function") clearStatisticsCache();
    }
    if (window.syncToFirestore && window.firebaseReady && window.firebaseAuth?.currentUser) {
      // Non-blocking sync
      setTimeout(() => {
        window.syncToFirestore(key, value).catch(err => console.warn(`Firestore sync failed for ${key}:`, err));
      }, 0);
    }
  } catch (error) {
    console.error(`Error in setLocalStorage for key ${key}:`, error);
  }
}

function removeLocalStorageKey(key) {
  try {
    localStorage.removeItem(key);
    LOCAL_STORAGE_CACHE.delete(key);
    if (key === "savedGames") {
      if (typeof invalidateProbabilityCachesForGames === "function") invalidateProbabilityCachesForGames();
      if (typeof clearStatisticsCache === "function") clearStatisticsCache();
    }
    if (window.syncToFirestore && window.firebaseReady && window.firebaseAuth?.currentUser) {
      setTimeout(() => {
        window.syncToFirestore(key, null).catch(err => console.warn(`Firestore removal sync failed for ${key}:`, err));
      }, 0);
    }
  } catch (error) {
    console.error(`Error removing localStorage key ${key}:`, error);
  }
}

function shouldAttemptJsonParse(raw) {
  if (typeof raw !== 'string') return false;
  const trimmed = raw.trim();
  if (!trimmed) return false;
  const first = trimmed[0];
  if (first === '{' || first === '[' || first === '"') return true;
  if (trimmed === 'true' || trimmed === 'false' || trimmed === 'null') return true;
  return /^-?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?$/.test(trimmed);
}

function getLocalStorage(key, defaultValue = null) {
  const raw = localStorage.getItem(key);
  if (raw === null) {
    LOCAL_STORAGE_CACHE.delete(key);
    if (defaultValue !== null) return defaultValue;
    if (key === "savedGames" || key === "freezerGames") return [];
    return {};
  }
  const cached = LOCAL_STORAGE_CACHE.get(key);
  if (cached && cached.raw === raw) return cached.parsed;
  if (!shouldAttemptJsonParse(raw)) {
    LOCAL_STORAGE_CACHE.set(key, { raw, parsed: raw });
    return raw;
  }
  try {
    const parsed = JSON.parse(raw);
    LOCAL_STORAGE_CACHE.set(key, { raw, parsed });
    return parsed;
  } catch (e) {
    if (defaultValue !== null) return defaultValue;
    if (key === "savedGames" || key === "freezerGames") return [];
    return {};
  }
}


// --- Icons ---
const Icons = { // SVG strings for icons to avoid multiple DOM elements
  AlertCircle: '<svg xmlns="http://www.w3.org/2000/svg" class="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"></circle><path d="M12 8v4m0 4h.01"></path></svg>',
  Undo: '<svg xmlns="http://www.w3.org/2000/svg" class="h-5 w-5 mr-1" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2"><path stroke-linecap="round" stroke-linejoin="round" d="M3 7v6h6M21 17a9 9 0 0 0-9-9c-2.5 0-4.75.9-6.5 2.4L3 11"/></svg>',
  Redo: '<svg xmlns="http://www.w3.org/2000/svg" class="h-5 w-5 mr-1" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2"><path stroke-linecap="round" stroke-linejoin="round" d="M21 7v6h-6M3 17a9 9 0 0 1 9-9c2.5 0 4.75.9 6.5 2.4L21 11"/></svg>',
  Trash: '<svg xmlns="http://www.w3.org/2000/svg" class="h-5 w-5 pointer-events-none" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2"><path stroke-linecap="round" stroke-linejoin="round" d="M6 18L18 6M6 6l12 12"/></svg>',
  Load: '<svg xmlns="http://www.w3.org/2000/svg" class="h-5 w-5 mr-1 pointer-events-none" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2"><path stroke-linecap="round" stroke-linejoin="round" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" /></svg>',
  Mic: '<svg xmlns="http://www.w3.org/2000/svg" class="h-4 w-4 pointer-events-none" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2"><path stroke-linecap="round" stroke-linejoin="round" d="M12 3a3 3 0 0 0-3 3v6a3 3 0 0 0 6 0V6a3 3 0 0 0-3-3Z"/><path stroke-linecap="round" stroke-linejoin="round" d="M19 10v2a7 7 0 0 1-14 0v-2M12 19v3M8 22h8"/></svg>',
  Trophy: '<svg xmlns="http://www.w3.org/2000/svg" class="h-8 w-8 inline-block mr-2" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2"><path stroke-linecap="round" stroke-linejoin="round" d="M3 10h18M7 10V4h10v6M7 10l-1 12h12 l-1-12M7 10h10m-5 12v-6"/></svg>',
};

// --- Bid Preset Logic ---
function savePresetBids() { setLocalStorage(PRESET_BIDS_KEY, presetBids); }
function openPresetEditorModal() {
  // No longer restrict to Pro Mode
  const settingsModal = document.getElementById("settingsModal");
  settingsModal?.classList.add("hidden");

  const existingModal = document.getElementById("presetEditorModal");
  if (existingModal) existingModal.remove();

  const modalHtml = `
      <div id="presetEditorModal" class="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center p-4 z-50 modal" role="dialog" aria-modal="true" aria-labelledby="presetEditorTitle">
          <div class="bg-white w-full max-w-md rounded-xl shadow-lg dark:bg-gray-800 p-6 transform transition-all">
              <div class="flex items-center justify-between mb-4">
                  <h2 id="presetEditorTitle" class="text-2xl font-bold text-gray-800 dark:text-white">Edit Bid Presets</h2>
                  <button type="button" onclick="closePresetEditorModal()" class="text-gray-500 hover:text-gray-700 dark:text-gray-300 dark:hover:text-gray-100 focus:outline-none focus:ring-2 focus:ring-blue-500 rounded-full p-1">
                      <svg xmlns="http://www.w3.org/2000/svg" class="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12" /></svg>
                  </button>
              </div>
              <p class="text-sm text-gray-600 dark:text-gray-300 mb-4">Customize quick bid buttons. Values must be multiples of 5.</p>
              <div id="presetInputs" class="space-y-3 max-h-64 overflow-y-auto pr-2 mb-4">
                  ${presetBids.filter(b => b !== "other").map((bid, index) => `
                      <div class="flex items-center space-x-3 preset-input-row">
                          <div class="flex-grow relative">
                              <input type="number" value="${bid}" min="5" max="360" step="5" class="w-full border border-gray-300 rounded-lg px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500 dark:bg-gray-700 dark:border-gray-600 dark:text-white" data-index="${index}" onchange="validatePresetInput(this)">
                              <div class="preset-error text-xs text-red-500 mt-1 hidden"></div>
                          </div>
                          <button type="button" onclick="removePreset(${index})" class="bg-gray-100 hover:bg-gray-200 dark:bg-gray-700 dark:hover:bg-gray-600 text-red-600 hover:text-red-700 dark:text-red-400 p-2 rounded-lg focus:outline-none focus:ring-2 focus:ring-red-500 transition-colors">${Icons.Trash}</button>
                      </div>`).join('')}
              </div>
              <div class="flex gap-2 flex-wrap mb-6">
                  <button type="button" onclick="addPreset()" class="flex items-center bg-blue-50 hover:bg-blue-100 dark:bg-blue-900/30 dark:hover:bg-blue-800/40 text-blue-600 dark:text-blue-400 px-4 py-2 rounded-lg font-medium focus:outline-none focus:ring-2 focus:ring-blue-500 transition-colors threed"><svg xmlns="http://www.w3.org/2000/svg" class="h-5 w-5 mr-1" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 4v16m8-8H4" /></svg>Add Preset</button>
              </div>
              <div id="presetErrorMsg" class="text-red-500 text-sm mb-4 hidden"></div>
              <div class="flex justify-end gap-3">
                  <button type="button" onclick="closePresetEditorModal()" class="px-4 py-2 border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50 dark:border-gray-600 dark:text-gray-300 dark:hover:bg-gray-700 focus:outline-none focus:ring-2 focus:ring-gray-400 transition-colors threed">Cancel</button>
                  <button type="button" onclick="savePresets()" class="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 dark:bg-blue-500 dark:hover:bg-blue-600 focus:outline-none focus:ring-2 focus:ring-blue-500 transition-colors threed">Save Changes</button>
              </div>
          </div>
      </div>`;
  document.body.insertAdjacentHTML('beforeend', modalHtml);
  const modalEl = document.getElementById("presetEditorModal");
  if (modalEl) {
    modalEl.addEventListener("click", (event) => {
      if (event.target === modalEl) closePresetEditorModal();
    });
    const content = modalEl.querySelector(".bg-white, .dark\\:bg-gray-800");
    if (content) content.addEventListener("click", (event) => event.stopPropagation());
  }
  activateModalEnvironment();
}
function closePresetEditorModal() {
  const modal = document.getElementById('presetEditorModal');
  if (modal) {
    modal.remove();
  }
  const settingsModal = document.getElementById("settingsModal");
  if (settingsModal) settingsModal.classList.remove("hidden");
  deactivateModalEnvironment();
}

function validatePresetInput(inputEl) {
  const val = Number(inputEl.value);
  const errDiv = inputEl.nextElementSibling;
  let msg = "";
  if (isNaN(val)) msg = "Must be a number.";
  else if (val <= 0) msg = "Must be > 0.";
  else if (val % 5 !== 0) msg = "Must be div by 5.";
  else if (val > 360) msg = "Cannot exceed 360.";
  else if (val > 180 && val !== 360) msg = "Only 360 allowed above 180.";
  errDiv.textContent = msg;
  errDiv.classList.toggle("hidden", !msg);
  return !msg;
}
function addPreset() {
  const container = document.getElementById('presetInputs');
  const newIdx = container.querySelectorAll('.preset-input-row').length;
  container.insertAdjacentHTML('beforeend', `
      <div class="flex items-center space-x-3 preset-input-row animate-fadeIn">
          <div class="flex-grow relative">
              <input type="number" value="120" min="5" max="360" step="5" class="w-full border border-gray-300 rounded-lg px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500 dark:bg-gray-700 dark:border-gray-600 dark:text-white" data-index="${newIdx}" onchange="validatePresetInput(this)">
              <div class="preset-error text-xs text-red-500 mt-1 hidden"></div>
          </div>
          <button type="button" onclick="removePreset(${newIdx})" class="bg-gray-100 hover:bg-gray-200 dark:bg-gray-700 dark:hover:bg-gray-600 text-red-600 hover:text-red-700 dark:text-red-400 p-2 rounded-lg focus:outline-none focus:ring-2 focus:ring-red-500 transition-colors">${Icons.Trash}</button>
      </div>`);
  container.scrollTop = container.scrollHeight;
}
function removePreset(index) {
  const rows = document.querySelectorAll('#presetInputs .preset-input-row');
  const errorMsgEl = document.getElementById('presetErrorMsg');
  if (rows.length <= 1) {
      errorMsgEl.textContent = 'Must have at least one preset.';
      errorMsgEl.classList.remove('hidden');
      setTimeout(() => errorMsgEl.classList.add('hidden'), 3000);
      return;
  }
  const rowToRemove = Array.from(rows).find(r => r.querySelector('input[data-index]')?.dataset.index == index);
  if (rowToRemove) {
      rowToRemove.classList.add('animate-fadeOut');
      setTimeout(() => {
          rowToRemove.remove();
          // Re-index remaining rows
          document.querySelectorAll('#presetInputs .preset-input-row').forEach((r, i) => {
              r.querySelector('input').dataset.index = i;
              r.querySelector('button').setAttribute('onclick', `removePreset(${i})`);
          });
      }, 150);
  }
}
function savePresets() {
  const inputs = Array.from(document.querySelectorAll('#presetInputs input'));
  const errorMsgEl = document.getElementById('presetErrorMsg');
  if (inputs.some(input => !validatePresetInput(input))) {
      errorMsgEl.textContent = 'Fix errors before saving.';
      errorMsgEl.classList.remove('hidden');
      return;
  }
  const newPresetsNum = inputs.map(input => Number(input.value));
  if (new Set(newPresetsNum).size !== newPresetsNum.length) {
      errorMsgEl.textContent = 'Duplicate values not allowed.';
      errorMsgEl.classList.remove('hidden');
      return;
  }
  if (newPresetsNum.length === 0) {
      errorMsgEl.textContent = 'At least one preset required.';
      errorMsgEl.classList.remove('hidden');
      return;
  }
  presetBids = [...newPresetsNum.sort((a, b) => a - b), "other"];
  savePresetBids();
  closePresetEditorModal();
  scheduleRender();
  showSaveIndicator("Bid presets updated");
}

function normalizePresetBidValues(values) {
  const normalized = Array.isArray(values)
    ? values.map(Number).filter(Number.isFinite)
    : [];
  const unique = [...new Set(normalized.map(value => Math.round(value / 5) * 5))]
    .filter(value => value > 0 && value <= 360 && (value <= 180 || value === 360))
    .sort((a, b) => a - b);
  if (!unique.length) throw new Error("At least one valid preset is required.");
  return unique;
}

function setPresetBidsFromValues(values) {
  presetBids = [...normalizePresetBidValues(values), "other"];
  savePresetBids();
  closePresetEditorModal();
  scheduleRender();
  showSaveIndicator("Bid presets updated");
  return presetBids;
}

// ---- js/modules/04-theme-ui-helpers.js ----
"use strict";

// --- Theme & UI Helpers ---
const IOS_STANDALONE_SAFE_AREA_FALLBACK_CLASS = "ios-standalone-safe-area-fallback";
const APP_CONTENT_OVERFLOWS_CLASS = "app-content-overflows";
const IOS_STANDALONE_SAFE_AREA_FALLBACK_TOP_PX = 44;

function getComputedSafeAreaInsetTop() {
  if (typeof document === "undefined" || !document.body || typeof getComputedStyle !== "function") return 0;
  const probe = document.createElement("div");
  probe.style.cssText = "position:fixed;top:0;left:0;padding-top:env(safe-area-inset-top,0px);visibility:hidden;pointer-events:none;";
  document.body.appendChild(probe);
  const value = parseFloat(getComputedStyle(probe).paddingTop);
  probe.remove();
  return Number.isFinite(value) ? value : 0;
}

function isProbablyIOSDevice() {
  if (typeof navigator === "undefined") return false;
  const userAgent = navigator.userAgent || "";
  const platform = navigator.platform || "";
  return /iPad|iPhone|iPod/.test(userAgent)
    || (platform === "MacIntel" && Number(navigator.maxTouchPoints) > 1);
}

function isStandaloneDisplayMode() {
  if (typeof window === "undefined") return false;
  const navigatorStandalone = window.navigator && window.navigator.standalone === true;
  const mediaStandalone = typeof window.matchMedia === "function"
    && window.matchMedia("(display-mode: standalone)").matches;
  return navigatorStandalone || mediaStandalone;
}

function shouldApplyStandaloneSafeAreaFallback({ isIOS, isStandalone, safeAreaInsetTop }) {
  return Boolean(isIOS && isStandalone && Number(safeAreaInsetTop) < 1);
}

function applyStandaloneSafeAreaFallback() {
  const body = document.getElementById("bodyRoot") || document.body;
  if (!body) return false;
  const needsFallback = shouldApplyStandaloneSafeAreaFallback({
    isIOS: isProbablyIOSDevice(),
    isStandalone: isStandaloneDisplayMode(),
    safeAreaInsetTop: getComputedSafeAreaInsetTop(),
  });
  body.classList.toggle(IOS_STANDALONE_SAFE_AREA_FALLBACK_CLASS, needsFallback);
  return needsFallback;
}

function shouldEnableAppViewportScroll(appScrollHeight, viewportHeight, safeAreaInsetTop = 0) {
  const contentHeight = Number(appScrollHeight);
  const availableHeight = Number(viewportHeight) - Math.max(0, Number(safeAreaInsetTop) || 0);
  if (!Number.isFinite(contentHeight) || !Number.isFinite(availableHeight) || availableHeight <= 0) return false;
  return contentHeight > availableHeight + 1;
}

function getViewportHeight() {
  if (typeof window === "undefined") return 0;
  const visualHeight = Number(window.visualViewport && window.visualViewport.height);
  if (Number.isFinite(visualHeight) && visualHeight > 0) return visualHeight;
  const innerHeight = Number(window.innerHeight);
  if (Number.isFinite(innerHeight) && innerHeight > 0) return innerHeight;
  return Number(document.documentElement && document.documentElement.clientHeight) || 0;
}

function syncAppViewportOverflowClass() {
  const body = document.getElementById("bodyRoot") || document.body;
  const app = document.getElementById("app");
  if (!body || !app) return false;
  const safeAreaInsetTop = body.classList.contains(IOS_STANDALONE_SAFE_AREA_FALLBACK_CLASS)
    ? IOS_STANDALONE_SAFE_AREA_FALLBACK_TOP_PX
    : getComputedSafeAreaInsetTop();
  const shouldScroll = shouldEnableAppViewportScroll(app.scrollHeight, getViewportHeight(), safeAreaInsetTop);
  body.classList.toggle(APP_CONTENT_OVERFLOWS_CLASS, shouldScroll);
  return shouldScroll;
}

function syncViewportCompatibilityClasses() {
  applyStandaloneSafeAreaFallback();
  syncAppViewportOverflowClass();
}

function scheduleViewportCompatibilitySync() {
  const schedule = typeof requestAnimationFrame === "function" ? requestAnimationFrame : (cb) => setTimeout(cb, 0);
  schedule(syncViewportCompatibilityClasses);
}

function enforceDarkMode() {
  const root = document.documentElement;
  if (!root.classList.contains("dark")) {
    root.classList.add("dark");
  }
  const metaTheme = document.querySelector('meta[name="theme-color"]');
  if (metaTheme) metaTheme.setAttribute("content", "#161b3d");
  // Remove legacy flag so we're not tempted to read it elsewhere.
  localStorage.removeItem("darkModeEnabled");
}
function initializeTheme() {
  const body = document.getElementById("bodyRoot") || document.body;

  // Classes that must ALWAYS be present, no matter which theme is selected
  const BASE_BODY_CLASSES = [
    "bg-gray-900",
    "text-white",
    "min-h-screen",
    "transition-colors", "duration-300",
    "liquid-glass"
  ];
  const baseClassString = BASE_BODY_CLASSES.join(" ");

  const ensureBaseClasses = (themeString) => {
    const tokens = new Set((themeString || "").split(/\s+/).filter(Boolean));
    let mutated = false;
    const deprecated = ["bg-white", "text-gray-800", "dark:bg-gray-900", "dark:text-white"];
    const dynamicCompatibility = [IOS_STANDALONE_SAFE_AREA_FALLBACK_CLASS, APP_CONTENT_OVERFLOWS_CLASS];
    for (const cls of deprecated) {
      if (tokens.delete(cls)) mutated = true;
    }
    for (const cls of dynamicCompatibility) {
      if (tokens.delete(cls)) mutated = true;
    }
    for (const cls of BASE_BODY_CLASSES) {
      if (!tokens.has(cls)) {
        tokens.add(cls);
        mutated = true;
      }
    }
    return { normalized: Array.from(tokens).join(" "), mutated };
  };

  // ------------------------------------------------------------------
  //  One-time migration for themes stored by older app versions
  // ------------------------------------------------------------------
  const savedTheme = getLocalStorage(THEME_KEY, "");

  if (savedTheme) {
    const { normalized, mutated } = ensureBaseClasses(savedTheme);
    if (mutated && normalized !== savedTheme) {
      setLocalStorage(THEME_KEY, normalized);
    }
    body.className = normalized;
    syncViewportCompatibilityClasses();
    return;
  }

  // ------------------------------------------------------------------
  //  Apply the theme (or fall back to default)
  // ------------------------------------------------------------------
  // First launch / user has never customised a theme
  body.className = `${baseClassString} theme-blue-red theme-cartoony`.trim();
  syncViewportCompatibilityClasses();
}
function isValidHexColor(colorString) {
  if (!colorString || typeof colorString !== 'string') return false;
  // Basic hex color validation (e.g., #RRGGBB or #RGB)
  return /^#([0-9A-F]{3}){1,2}$/i.test(colorString);
}

function sanitizeHexColor(colorString) {
  if (typeof colorString !== 'string') return '';
  const trimmed = colorString.trim();
  if (!trimmed) return '';
  const withoutQuotes = trimmed.replace(/^['"]+|['"]+$/g, '');
  if (!withoutQuotes) return '';
  const candidate = withoutQuotes.startsWith('#') ? withoutQuotes : `#${withoutQuotes}`;
  return isValidHexColor(candidate) ? candidate : '';
}

function initializeCustomThemeColors() {
  const rootStyles = getComputedStyle(document.documentElement);
  const defaultUsColor = rootStyles.getPropertyValue('--primary-color').trim() || "#3b82f6";
  const defaultDemColor = rootStyles.getPropertyValue('--accent-color').trim() || "#ef4444";

  const storedUsColor = getLocalStorage('customUsColor', '');
  const storedDemColor = getLocalStorage('customDemColor', '');

  const body = document.getElementById('bodyRoot');
  const usPicker = document.getElementById('usColorPicker');
  const demPicker = document.getElementById('demColorPicker');

  const usColor = sanitizeHexColor(storedUsColor);
  if (usColor) {
    if (storedUsColor !== usColor) setLocalStorage('customUsColor', usColor);
    if (body) body.style.setProperty('--primary-color', usColor);
    if (usPicker) usPicker.value = usColor;
  } else {
    if (storedUsColor !== null) { // Warn only when a value existed
      console.warn(`Invalid customUsColor ("${storedUsColor}") in localStorage. Using default.`);
      removeLocalStorageKey('customUsColor');
    }
    if (body) body.style.setProperty('--primary-color', defaultUsColor);
    if (usPicker) usPicker.value = defaultUsColor;
  }

  const demColor = sanitizeHexColor(storedDemColor);
  if (demColor) {
    if (storedDemColor !== demColor) setLocalStorage('customDemColor', demColor);
    if (body) body.style.setProperty('--accent-color', demColor);
    if (demPicker) demPicker.value = demColor;
  } else {
    if (storedDemColor !== null) {
      console.warn(`Invalid customDemColor ("${storedDemColor}") in localStorage. Using default.`);
      removeLocalStorageKey('customDemColor');
    }
    if (body) body.style.setProperty('--accent-color', defaultDemColor);
    if (demPicker) demPicker.value = defaultDemColor;
  }
  updatePreview(); // Ensure preview matches
}
function applyCustomThemeColors() {
  const body = document.getElementById('bodyRoot');
  const usPicker = document.getElementById('usColorPicker');
  const demPicker = document.getElementById('demColorPicker');

  const usColor = sanitizeHexColor(usPicker ? usPicker.value : '');
  const demColor = sanitizeHexColor(demPicker ? demPicker.value : '');

  if (usColor) {
    if (body) body.style.setProperty('--primary-color', usColor);
    setLocalStorage('customUsColor', usColor);
  } else {
    removeLocalStorageKey('customUsColor');
  }

  if (demColor) {
    if (body) body.style.setProperty('--accent-color', demColor);
    setLocalStorage('customDemColor', demColor);
  } else {
    removeLocalStorageKey('customDemColor');
  }

  closeThemeModal(null); // Pass null if event is not available or needed
}
function resetThemeColors() {
  const defaultUs = "#3b82f6", defaultDem = "#ef4444";
  document.getElementById('bodyRoot').style.setProperty('--primary-color', defaultUs);
  document.getElementById('bodyRoot').style.setProperty('--accent-color', defaultDem);
  removeLocalStorageKey('customUsColor');
  removeLocalStorageKey('customDemColor');
  const usPicker = document.getElementById('usColorPicker');
  const demPicker = document.getElementById('demColorPicker');
  if (usPicker) usPicker.value = defaultUs;
  if (demPicker) demPicker.value = defaultDem;
  updatePreview();
}
function hslToHex(h, s, l) { // Helper for random colors
  s /= 100; l /= 100;
  const k = n => (n + h / 30) % 12;
  const a = s * Math.min(l, 1 - l);
  const f = n => l - a * Math.max(-1, Math.min(k(n) - 3, Math.min(9 - k(n), 1)));
  return "#" + [0, 8, 4].map(n => Math.round(f(n) * 255).toString(16).padStart(2, '0')).join('');
}
function randomizeThemeColors() {
  const h = Math.floor(Math.random() * 360);
  const s = Math.floor(Math.random() * 51) + 50; // Saturation 50-100%
  const l = Math.floor(Math.random() * 41) + 30; // Lightness 30-70%
  document.getElementById('usColorPicker').value = hslToHex(h, s, l);
  document.getElementById('demColorPicker').value = hslToHex((h + 180) % 360, s, l); // Complementary
  updatePreview();
}
function updatePreview() {
  const usColor = document.getElementById('usColorPicker')?.value;
  const demColor = document.getElementById('demColorPicker')?.value;
  const previewUs = document.getElementById('previewUs');
  const previewDem = document.getElementById('previewDem');
  if (previewUs && usColor) previewUs.style.backgroundColor = usColor;
  if (previewDem && demColor) previewDem.style.backgroundColor = demColor;
}
 function openThemeModal(event) {
  if (event) { event.preventDefault(); event.stopPropagation(); }
  document.getElementById("settingsModal")?.classList.add("hidden");
  const themeModalEl = document.getElementById("themeModal");
  if (themeModalEl) {
      themeModalEl.classList.remove("hidden");
      const content = themeModalEl.querySelector(".bg-white, .dark\\:bg-gray-800");
      if (content) content.onclick = e => e.stopPropagation(); // Prevent closing on content click
      initializeCustomThemeColors(); // Ensure pickers and preview are up-to-date
  }
}
function closeThemeModal(event) {
  if (event) { event.preventDefault(); event.stopPropagation(); }
  document.getElementById("themeModal")?.classList.add("hidden");
  document.getElementById("settingsModal")?.classList.remove("hidden"); // Show settings modal again
}
function showSaveIndicator(message = "Saved") {
  const el = document.getElementById("saveIndicator");
  if (!el) return;
  el.textContent = message;
  el.classList.remove("hidden", "bg-red-600"); // Remove error class if present
  el.classList.add("show");
  setTimeout(() => { el.classList.remove("show"); setTimeout(() => el.classList.add("hidden"), 150); }, 1000);
}

// ---- js/modules/05-game-state-management.js ----
"use strict";

// --- Game State Management ---
function updateState(newState) {
  const nextState = { ...newState };

  const has = (obj, key) => Object.prototype.hasOwnProperty.call(obj, key);

  if (has(nextState, 'rounds') && nextState.rounds !== state.rounds) {
    roundsVersion += 1;
  }

  if (has(nextState, 'usPlayers')) {
    nextState.usPlayers = ensurePlayersArray(nextState.usPlayers);
    if (!has(nextState, 'usTeamName')) {
      nextState.usTeamName = deriveTeamDisplay(nextState.usPlayers);
    }
  } else if (has(nextState, 'usTeamName')) {
    const parsed = parseLegacyTeamName(nextState.usTeamName);
    nextState.usPlayers = ensurePlayersArray(parsed);
    nextState.usTeamName = deriveTeamDisplay(parsed, nextState.usTeamName);
  }

  if (has(nextState, 'demPlayers')) {
    nextState.demPlayers = ensurePlayersArray(nextState.demPlayers);
    if (!has(nextState, 'demTeamName')) {
      nextState.demTeamName = deriveTeamDisplay(nextState.demPlayers);
    }
  } else if (has(nextState, 'demTeamName')) {
    const parsed = parseLegacyTeamName(nextState.demTeamName);
    nextState.demPlayers = ensurePlayersArray(parsed);
    nextState.demTeamName = deriveTeamDisplay(parsed, nextState.demTeamName);
  }

  if (has(nextState, 'startingTotals')) {
    nextState.startingTotals = sanitizeTotals(nextState.startingTotals);
  }

  if (has(nextState, 'misdealDealers')) {
    nextState.misdealDealers = normalizeMisdealDealers(nextState.misdealDealers);
  }

  state = { ...state, ...nextState };
  scheduleRender();
}
function resetGame() {
  const isProMode = JSON.parse(localStorage.getItem(PRO_MODE_KEY) || "false");
  resetRenderAnimationState();
  updateState({
    ...DEFAULT_STATE,
    usTeamName : "",      // blank ⇒ UI falls back to "Us"
    demTeamName: "",      // blank ⇒ UI falls back to "Dem"
    showWinProbability: isProMode,
    pendingPenalty : null
  });
  confettiTriggered = false;
  ephemeralCustomBid = "";
  ephemeralPoints = "";
  activeScoreKeypadTarget = "";
  scoreKeypadShouldAnimate = false;
  if (scoreKeypadCloseTimer) clearTimeout(scoreKeypadCloseTimer);
  scoreKeypadCloseTimer = null;
  localStorage.removeItem(ACTIVE_GAME_KEY);
  // Attempt to also clear from Firebase if user is signed in
  if (window.syncToFirestore && window.firebaseReady && window.firebaseAuth?.currentUser) {
      window.syncToFirestore(ACTIVE_GAME_KEY, null); // Sync deletion of active game
  }
}
function loadCurrentGameState() {
  let loadedState = null; // Initialize to null
  try {
    const storedStateString = localStorage.getItem(ACTIVE_GAME_KEY);
    if (storedStateString) {
loadedState = JSON.parse(storedStateString);
    }
  } catch (e) {
    console.error("Error parsing activeGameState from localStorage. Will reset to default state.", e);
    localStorage.removeItem(ACTIVE_GAME_KEY); // Critical: remove the corrupted state
    // loadedState remains null, so it will fall through to using DEFAULT_STATE
  }

  if (loadedState && typeof loadedState === 'object' && loadedState !== null) {
    // Ensure all DEFAULT_STATE keys are present, preferring loaded values
    const completeLoadedState = { ...DEFAULT_STATE, ...loadedState };
    completeLoadedState.rounds = Array.isArray(loadedState.rounds) ? loadedState.rounds : [];
    completeLoadedState.undoneRounds = Array.isArray(loadedState.undoneRounds) ? loadedState.undoneRounds : [];
    // Transient flag must never persist across loads; a stuck `true` (from an
    // older build) would freeze every submit. Always start fresh.
    completeLoadedState.isSubmittingRound = false;
    const now = Date.now();
    const hasRounds = Array.isArray(completeLoadedState.rounds) && completeLoadedState.rounds.length > 0;
    const startTimeValid = isStartTimestampActive(completeLoadedState.startTime);
    const timerWasRunning = startTimeValid && !completeLoadedState.gameOver && hasRounds;
    const sanitizedAccumulated = clampDurationMs(completeLoadedState.accumulatedTime);

    if (timerWasRunning) {
      if (typeof completeLoadedState.timerLastSavedAt !== 'number') {
        // Legacy snapshots did not pre-accumulate time; cap what we add just in case.
        completeLoadedState.accumulatedTime = calculateSafeTimeAccumulation(sanitizedAccumulated, completeLoadedState.startTime, now);
      } else {
        completeLoadedState.accumulatedTime = sanitizedAccumulated;
      }
      completeLoadedState.startTime = now; // Resume timer from now so offline time is not double-counted.
    } else {
      completeLoadedState.accumulatedTime = sanitizedAccumulated;
      completeLoadedState.startTime = null;
    }

    completeLoadedState.timerLastSavedAt = now;
    // Ensure showWinProbability is correctly set from localStorage PRO_MODE_KEY
    completeLoadedState.showWinProbability = JSON.parse(localStorage.getItem(PRO_MODE_KEY) || "false"); // Add try-catch for this too
    completeLoadedState.startingTotals = sanitizeTotals(completeLoadedState.startingTotals);
    updateState(completeLoadedState);
  } else {
    if (loadedState) {
      localStorage.removeItem(ACTIVE_GAME_KEY); // Remove invalid structure
    }
    // Fallback to default state
    updateState({
...DEFAULT_STATE,
usTeamName: "", // Or load from a separate team name storage if you have one
demTeamName: "",
showWinProbability: JSON.parse(localStorage.getItem(PRO_MODE_KEY) || "false"), // Add try-catch here as well
startTime: null,
timerLastSavedAt: null
    });
  }
}
function saveCurrentGameState() {
  if (state.gameOver) {
    localStorage.removeItem(ACTIVE_GAME_KEY);
    if (window.syncToFirestore && window.firebaseReady && window.firebaseAuth?.currentUser) {
      window.syncToFirestore(ACTIVE_GAME_KEY, null);
    }
  } else {
    const now = Date.now();
    const timerRunning = isStartTimestampActive(state.startTime);
    const baseAccumulated = clampDurationMs(state.accumulatedTime);
    const finalAccumulated = timerRunning
      ? calculateSafeTimeAccumulation(baseAccumulated, state.startTime, now)
      : baseAccumulated;
    const snapshot = {
      ...state,
      accumulatedTime: finalAccumulated,
      startTime: timerRunning ? now : null,
      timerLastSavedAt: now,
      startingTotals: sanitizeTotals(state.startingTotals),
    };
    state.timerLastSavedAt = now;
    setLocalStorage(ACTIVE_GAME_KEY, snapshot); // This now handles Firestore sync too
    showSaveIndicator();
  }
}

// ---- js/modules/06-team-stats-helpers.js ----
"use strict";

// --- Team Stats Helpers ---
function normalizeTeamsStorage(raw) {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
    return { data: {}, changed: Boolean(raw && raw !== null) };
  }

  const working = { ...raw };
  delete working.__storageVersion;

  const entries = Object.entries(working);
  if (!entries.length) {
    return { data: {}, changed: raw.__storageVersion !== TEAM_STORAGE_VERSION };
  }

  const isAlreadyNew = entries.every(([, value]) => value && typeof value === 'object' && Array.isArray(value.players));
  if (raw.__storageVersion === TEAM_STORAGE_VERSION && isAlreadyNew) {
    const cleaned = {};
    entries.forEach(([key, value]) => {
      cleaned[key] = {
        players: ensurePlayersArray(value.players),
        displayName: deriveTeamDisplay(value.players, value.displayName || ''),
        wins: Number(value.wins) || 0,
        losses: Number(value.losses) || 0,
        gamesPlayed: Number(value.gamesPlayed) || 0,
      };
    });
    return { data: cleaned, changed: false };
  }

  const converted = {};
  entries.forEach(([legacyName, payload]) => {
    let players = [];
    let stats = { wins: 0, losses: 0, gamesPlayed: 0 };

    if (payload && typeof payload === 'object' && !Array.isArray(payload) && Array.isArray(payload.players)) {
      players = canonicalizePlayers(payload.players);
      stats = {
        wins: Number(payload.wins) || 0,
        losses: Number(payload.losses) || 0,
        gamesPlayed: Number(payload.gamesPlayed) || 0,
      };
    } else {
      players = canonicalizePlayers(parseLegacyTeamName(legacyName));
      if (payload && typeof payload === 'object' && !Array.isArray(payload)) {
        stats = {
          wins: Number(payload.wins) || 0,
          losses: Number(payload.losses) || 0,
          gamesPlayed: Number(payload.gamesPlayed) || 0,
        };
      }
    }

    const key = buildTeamKey(players);
    const displayName = deriveTeamDisplay(players, legacyName);
    if (!converted[key]) {
      converted[key] = { players: canonicalizePlayers(players), displayName, wins: 0, losses: 0, gamesPlayed: 0 };
    }
    converted[key].wins += stats.wins;
    converted[key].losses += stats.losses;
    converted[key].gamesPlayed += stats.gamesPlayed;
    if (!converted[key].displayName) converted[key].displayName = displayName;
  });

  return { data: converted, changed: true };
}

function getTeamsObject() {
  const raw = getLocalStorage("teams") || {};
  const { data, changed } = normalizeTeamsStorage(raw);
  if (changed) setTeamsObject(data);
  return data;
}

function setTeamsObject(obj) {
  const entries = {};
  Object.entries(obj || {}).forEach(([key, value]) => {
    if (!key || !value) return;
    entries[key] = {
      players: canonicalizePlayers(value.players),
      displayName: deriveTeamDisplay(canonicalizePlayers(value.players), value.displayName || ''),
      wins: Number(value.wins) || 0,
      losses: Number(value.losses) || 0,
      gamesPlayed: Number(value.gamesPlayed) || 0,
    };
  });
  setLocalStorage("teams", { __storageVersion: TEAM_STORAGE_VERSION, ...entries });
}

function ensureTeamEntry(teamsObj, players, fallbackDisplay = '') {
  const normalizedPlayers = canonicalizePlayers(players);
  const key = buildTeamKey(normalizedPlayers);
  if (!key) return { teams: teamsObj, key: null };
  if (!teamsObj[key]) {
    teamsObj[key] = {
      players: normalizedPlayers,
      displayName: deriveTeamDisplay(normalizedPlayers, fallbackDisplay || 'Unnamed Team'),
      wins: 0,
      losses: 0,
      gamesPlayed: 0,
    };
  } else {
    teamsObj[key].players = ensurePlayersArray(teamsObj[key].players);
    if (!teamsObj[key].displayName) {
      teamsObj[key].displayName = deriveTeamDisplay(normalizedPlayers, fallbackDisplay || 'Unnamed Team');
    }
  }
  return { teams: teamsObj, key };
}

function applyTeamResultDelta(teamsObj, { usPlayers, demPlayers, usDisplay, demDisplay, winner }, direction = 1) {
  if (!direction) return false;

  const normalizedUs = canonicalizePlayers(usPlayers);
  const normalizedDem = canonicalizePlayers(demPlayers);
  const usName = deriveTeamDisplay(normalizedUs, usDisplay || 'Us') || 'Us';
  const demName = deriveTeamDisplay(normalizedDem, demDisplay || 'Dem') || 'Dem';
  const usKey = buildTeamKey(normalizedUs);
  const demKey = buildTeamKey(normalizedDem);
  if (!usKey || !demKey) return false;

  if (direction > 0) {
    ensureTeamEntry(teamsObj, normalizedUs, usName);
    ensureTeamEntry(teamsObj, normalizedDem, demName);
  }

  const usEntry = teamsObj[usKey];
  const demEntry = teamsObj[demKey];
  if (!usEntry || !demEntry) return false;

  const clamp = (value) => Math.max(0, Number.isFinite(value) ? value : 0);

  usEntry.players = canonicalizePlayers(usEntry.players);
  demEntry.players = canonicalizePlayers(demEntry.players);
  if (!usEntry.displayName) usEntry.displayName = usName;
  if (!demEntry.displayName) demEntry.displayName = demName;

  usEntry.gamesPlayed = clamp((Number(usEntry.gamesPlayed) || 0) + direction);
  demEntry.gamesPlayed = clamp((Number(demEntry.gamesPlayed) || 0) + direction);

  if (winner === 'us') {
    usEntry.wins = clamp((Number(usEntry.wins) || 0) + direction);
    demEntry.losses = clamp((Number(demEntry.losses) || 0) + direction);
  } else if (winner === 'dem') {
    demEntry.wins = clamp((Number(demEntry.wins) || 0) + direction);
    usEntry.losses = clamp((Number(usEntry.losses) || 0) + direction);
  }

  return true;
}

function updateTeamsStatsOnGameEnd(winner) {
  const teams = getTeamsObject();
  const usTeam = getTeamSnapshotForSide(state, "us");
  const demTeam = getTeamSnapshotForSide(state, "dem");
  const updated = applyTeamResultDelta(teams, {
    usPlayers: usTeam.players,
    demPlayers: demTeam.players,
    usDisplay: usTeam.display,
    demDisplay: demTeam.display,
    winner,
  }, 1);
  if (updated) setTeamsObject(teams);
}
function recalcTeamsStats() {
  const teams = getTeamsObject();
  Object.values(teams).forEach(entry => {
    if (!entry) return;
    entry.gamesPlayed = 0;
    entry.wins = 0;
    entry.losses = 0;
  });

  const accumulateFromGame = (game) => {
    if (!game) return;
    const usPlayers = canonicalizePlayers(game.usPlayers || parseLegacyTeamName(game.usTeamName || game.usName));
    const demPlayers = canonicalizePlayers(game.demPlayers || parseLegacyTeamName(game.demTeamName || game.demName));
    const usDisplay = deriveTeamDisplay(usPlayers, game.usTeamName || game.usName || 'Us');
    const demDisplay = deriveTeamDisplay(demPlayers, game.demTeamName || game.demName || 'Dem');
    const winner = game.winner === 'us' || game.winner === 'dem' ? game.winner : null;
    applyTeamResultDelta(teams, { usPlayers, demPlayers, usDisplay, demDisplay, winner }, 1);
  };

  const savedGames = getLocalStorage('savedGames', []);
  savedGames.forEach(accumulateFromGame);

  if (state.gameOver && Array.isArray(state.rounds) && state.rounds.length) {
    accumulateFromGame({
      usPlayers: ensurePlayersArray(state.usPlayers),
      demPlayers: ensurePlayersArray(state.demPlayers),
      usTeamName: state.usTeamName,
      demTeamName: state.demTeamName,
      winner: state.winner,
    });
  }

  setTeamsObject(teams);
}
function addTeamIfNotExists(players, display = '') {
  const teams = getTeamsObject();
  const { key } = ensureTeamEntry(teams, players, display);
  if (key) setTeamsObject(teams);
}

// ---- js/modules/07-menu-modal.js ----
"use strict";

// --- Menu & Modal Toggling ---

const DEALER_INPUT_IDS = ["dealer1", "dealer2", "dealer3", "dealer4"];
const DEALER_SUGGESTION_LIMIT = 6;
const dealerSuggestionControllers = [];

function destroyDealerSuggestionControllers() {
  while (dealerSuggestionControllers.length) {
    const controller = dealerSuggestionControllers.pop();
    controller?.destroy?.();
  }
}

function getDealerInput(inputId) {
  return document.getElementById(inputId);
}

function getDealerInputName(inputId) {
  return sanitizePlayerName(getDealerInput(inputId)?.value || "");
}

function getDealerExcludedNames(activeInputId) {
  return DEALER_INPUT_IDS
    .filter(inputId => inputId !== activeInputId)
    .map(getDealerInputName)
    .filter(Boolean);
}

function hasDuplicateDealerNames(dealers) {
  const seen = new Set();
  return dealers.some((dealer) => {
    const key = sanitizePlayerName(dealer).toLowerCase();
    if (!key) return false;
    if (seen.has(key)) return true;
    seen.add(key);
    return false;
  });
}

function shouldUseMobileDealerLayout() {
  return typeof window !== "undefined"
    && typeof window.matchMedia === "function"
    && window.matchMedia("(max-width: 640px), (pointer: coarse)").matches;
}

function shouldAutoFocusDealerInput() {
  return !(typeof window !== "undefined"
    && typeof window.matchMedia === "function"
    && window.matchMedia("(pointer: coarse)").matches);
}

function scrollDealerElementIntoView(element) {
  if (!element || !shouldUseMobileDealerLayout()) return;
  window.setTimeout(() => {
    element.scrollIntoView?.({ block: "center", inline: "nearest" });
  }, 80);
}

function focusNextDealerField(currentInputId) {
  const currentIndex = DEALER_INPUT_IDS.indexOf(currentInputId);
  const followingIds = currentIndex >= 0 ? DEALER_INPUT_IDS.slice(currentIndex + 1) : [];
  const nextInputId = followingIds.find(inputId => !getDealerInputName(inputId)) || followingIds[0];
  const nextInput = nextInputId ? getDealerInput(nextInputId) : null;

  if (nextInput) {
    window.setTimeout(() => {
      nextInput.focus();
      scrollDealerElementIntoView(nextInput);
    }, 0);
    return;
  }

  const submitButton = document.getElementById("dealerOrderSubmitBtn")
    || document.querySelector("#dealerOrderForm button[type='submit']");
  window.setTimeout(() => submitButton?.focus(), 0);
}

function hideDealerSuggestionsExcept(activeInputId = "") {
  DEALER_INPUT_IDS.forEach((inputId) => {
    if (inputId === activeInputId) return;
    setDealerSuggestionsVisibility(document.getElementById(`${inputId}Suggestions`), false);
  });
}

function setDealerSuggestionsVisibility(container, visible) {
  if (!container) return;
  container.classList.toggle("hidden", !visible);
  const inputId = container.id?.replace(/Suggestions$/, "");
  if (inputId) {
    document.getElementById(inputId)?.setAttribute("aria-expanded", visible ? "true" : "false");
  }
}

function renderDealerSuggestionItems(container, suggestions, onSelect) {
  if (!container) return;
  if (!suggestions.length) {
    container.innerHTML = "";
    setDealerSuggestionsVisibility(container, false);
    return;
  }

  container.innerHTML = suggestions
    .map((name, index) => `<button type="button" id="${container.id}Option${index}" role="option" class="dealer-suggestion-option block w-full px-4 py-2 text-left text-sm text-gray-700 transition-colors hover:bg-blue-50 focus:bg-blue-50 focus:outline-none dark:text-white dark:hover:bg-gray-600 dark:focus:bg-gray-600" data-suggested-name="${escapeAttribute(name)}">${escapeHtml(name)}</button>`)
    .join("");
  setDealerSuggestionsVisibility(container, true);

  Array.from(container.querySelectorAll("button[data-suggested-name]")).forEach((button) => {
    let selected = false;
    const handleSelect = (event) => {
      event?.preventDefault?.();
      if (selected) return;
      selected = true;
      onSelect(button.dataset.suggestedName || "");
    };
    if (typeof window !== "undefined" && "PointerEvent" in window) {
      button.addEventListener("pointerdown", handleSelect);
      button.addEventListener("click", handleSelect);
    } else {
      button.addEventListener("mousedown", handleSelect);
      button.addEventListener("touchstart", handleSelect, { passive: false });
      button.addEventListener("click", handleSelect);
    }
  });
}

function createDealerSuggestionController(inputId) {
  const input = getDealerInput(inputId);
  const container = document.getElementById(`${inputId}Suggestions`);
  if (!input || !container) return null;

  let blurTimeoutId = null;

  const updateSuggestions = () => {
    clearTimeout(blurTimeoutId);
    hideDealerSuggestionsExcept(inputId);
    const orderedSuggestions = refreshPlayerSuggestions();
    const currentName = sanitizePlayerName(input.value).toLowerCase();
    const filteredSuggestions = getFilteredPlayerSuggestions(
      orderedSuggestions,
      input.value,
      DEALER_SUGGESTION_LIMIT,
      getDealerExcludedNames(inputId)
    ).filter(name => name.toLowerCase() !== currentName);

    renderDealerSuggestionItems(container, filteredSuggestions, (selectedName) => {
      input.value = selectedName;
      input.dispatchEvent(new Event("input", { bubbles: true }));
      setDealerSuggestionsVisibility(container, false);
      focusNextDealerField(inputId);
    });
  };

  const handleFocus = () => {
    updateSuggestions();
    scrollDealerElementIntoView(input);
  };
  const handleInput = () => updateSuggestions();
  const handleKeydown = (event) => {
    if (event.key === "Escape") {
      setDealerSuggestionsVisibility(container, false);
      return;
    }
    if (event.key !== "Enter" || event.isComposing) return;
    event.preventDefault();
    setDealerSuggestionsVisibility(container, false);
    if (getDealerInputName(inputId)) focusNextDealerField(inputId);
  };
  const handleBlur = () => {
    clearTimeout(blurTimeoutId);
    blurTimeoutId = window.setTimeout(() => setDealerSuggestionsVisibility(container, false), 180);
  };

  input.addEventListener("focus", handleFocus);
  input.addEventListener("input", handleInput);
  input.addEventListener("keydown", handleKeydown);
  input.addEventListener("blur", handleBlur);

  return {
    destroy() {
      clearTimeout(blurTimeoutId);
      input.removeEventListener("focus", handleFocus);
      input.removeEventListener("input", handleInput);
      input.removeEventListener("keydown", handleKeydown);
      input.removeEventListener("blur", handleBlur);
      container.innerHTML = "";
      setDealerSuggestionsVisibility(container, false);
    },
    update: updateSuggestions,
  };
}

function setupDealerNameSuggestions() {
  destroyDealerSuggestionControllers();
  DEALER_INPUT_IDS.forEach((inputId) => {
    const controller = createDealerSuggestionController(inputId);
    if (controller) {
      dealerSuggestionControllers.push(controller);
    }
  });
}

function toggleMenu(e) {
  if (e) e.stopPropagation();
  const menu = document.getElementById("menu");
  const icon = document.getElementById("hamburgerIcon");
  const overlay = document.getElementById("menuOverlay");
  const isOpen = menu.classList.toggle("show");
  icon.classList.toggle("open", isOpen);
  overlay.classList.toggle("show", isOpen);
  document.body.classList.toggle("overflow-hidden", isOpen);
}
function closeMenuOverlay() {
  document.getElementById("menu")?.classList.remove("show");
  document.getElementById("hamburgerIcon")?.classList.remove("open");
  document.getElementById("menuOverlay")?.classList.remove("show");
  document.body.classList.remove("overflow-hidden");
}

function activateModalEnvironment() {
  document.body.classList.add("modal-open");
  document.getElementById("app")?.classList.add("modal-active");
}

function deactivateModalEnvironment() {
  const anyOpenModal = Array.from(document.querySelectorAll(".modal"))
    .some(modal => !modal.classList.contains("hidden"));
  if (!anyOpenModal) {
    document.body.classList.remove("modal-open");
    document.getElementById("app")?.classList.remove("modal-active");
  }
}

function openModal(modalId) {
  const modal = document.getElementById(modalId);
  modal?.classList.remove("hidden");
  activateModalEnvironment();
  modal?.focus(); // For accessibility
}
function closeModal(modalId) {
  document.getElementById(modalId)?.classList.add("hidden");
  deactivateModalEnvironment();
}
function openSavedGamesModal() {
  updateGamesCount();
  switchGamesTab('completed'); // Default to completed games
  renderGamesWithFilter(); // Render based on default filter/sort
  openModal("savedGamesModal");
}
function closeSavedGamesModal() { closeModal("savedGamesModal"); }
function openConfirmationModal(message, yesCb, noCb) {
  document.getElementById("confirmationModalMessage").textContent = message;
  confirmationCallback = yesCb; noCallback = noCb;
  openModal("confirmationModal");
  // Re-bind buttons to avoid multiple listeners if not careful
  const yesBtn = document.getElementById("confirmModalButton");
  const noBtn = document.getElementById("noModalButton");
  const newYes = yesBtn.cloneNode(true); yesBtn.parentNode.replaceChild(newYes, yesBtn);
  const newNo = noBtn.cloneNode(true); noBtn.parentNode.replaceChild(newNo, noBtn);
  newYes.addEventListener("click", (e) => { e.stopPropagation(); if (confirmationCallback) confirmationCallback(); });
  newNo.addEventListener("click", (e) => { e.stopPropagation(); if (noCallback) noCallback(); });
}
function closeConfirmationModal() { closeModal("confirmationModal"); confirmationCallback = null; noCallback = null; }
function openTeamSelectionModal() { populateTeamSelects(); openModal("teamSelectionModal"); }
function closeTeamSelectionModal() { closeModal("teamSelectionModal"); }
function openDealerOrderModal() {
  const form = document.getElementById("dealerOrderForm");
  if (form) form.reset();
  refreshPlayerSuggestions();
  setupDealerNameSuggestions();
  openModal("dealerOrderModal");
  const firstDealerInput = getDealerInput("dealer1");
  if (shouldAutoFocusDealerInput()) {
    firstDealerInput?.focus();
  } else {
    scrollDealerElementIntoView(firstDealerInput);
  }
}
function closeDealerOrderModal() {
  destroyDealerSuggestionControllers();
  closeModal("dealerOrderModal");
}
function openDealerPairSelectionModal() {
  // Populate the button text with dealer names
  if (state.dealers && state.dealers.length === 4) {
    const pair13Text = `${state.dealers[0]} & ${state.dealers[2]}`;
    const pair24Text = `${state.dealers[1]} & ${state.dealers[3]}`;
    document.getElementById("pair13Text").textContent = pair13Text;
    document.getElementById("pair24Text").textContent = pair24Text;
  }
  openModal("dealerPairSelectionModal");
}
function closeDealerPairSelectionModal() { closeModal("dealerPairSelectionModal"); }
function handleDealerPairSelection(pair) {
  closeDealerPairSelectionModal();
  
  // Set up the team players based on selection
  if (pair === '13') {
    // Dealers 1 & 3 are "Us", Dealers 2 & 4 are "Dem"
    window.prePopulatedTeamData = {
      usPlayers: [state.dealers[0], state.dealers[2]],
      demPlayers: [state.dealers[1], state.dealers[3]]
    };
  } else if (pair === '24') {
    // Dealers 2 & 4 are "Us", Dealers 1 & 3 are "Dem"
    window.prePopulatedTeamData = {
      usPlayers: [state.dealers[1], state.dealers[3]],
      demPlayers: [state.dealers[0], state.dealers[2]]
    };
  }
  
  // Open team selection modal with pre-populated data
  openTeamSelectionModal();
}
function handleDealerOrderSubmit(event) {
  event.preventDefault();
  const dealer1 = sanitizePlayerName(document.getElementById("dealer1")?.value || "");
  const dealer2 = sanitizePlayerName(document.getElementById("dealer2")?.value || "");
  const dealer3 = sanitizePlayerName(document.getElementById("dealer3")?.value || "");
  const dealer4 = sanitizePlayerName(document.getElementById("dealer4")?.value || "");
  
  // Validate that all 4 dealers are entered
  if (!dealer1 || !dealer2 || !dealer3 || !dealer4) {
    alert("Please enter all 4 dealer names to continue.");
    return;
  }
  
  const dealers = [dealer1, dealer2, dealer3, dealer4];
  if (hasDuplicateDealerNames(dealers)) {
    alert("Each dealer needs a different name.");
    return;
  }

  updateState({ dealers });
  saveCurrentGameState();
  closeDealerOrderModal();
}
function openResumeGameModal() {
  const form = document.getElementById("resumeGameForm");
  const errorEl = document.getElementById("resumeGameError");
  if (errorEl) {
    errorEl.textContent = "";
    errorEl.classList.add("hidden");
  }
  if (form) form.reset();
  refreshPlayerSuggestions();

  const totals = getCurrentTotals();
  const basePlayers = {
    us: (() => {
      const players = ensurePlayersArray(state.usPlayers);
      if (players.some(Boolean)) return players;
      return ensurePlayersArray(parseLegacyTeamName(state.usTeamName || ""));
    })(),
    dem: (() => {
      const players = ensurePlayersArray(state.demPlayers);
      if (players.some(Boolean)) return players;
      return ensurePlayersArray(parseLegacyTeamName(state.demTeamName || ""));
    })(),
  };

  const usPlayerOneInput = document.getElementById("resumeUsPlayerOne");
  const usPlayerTwoInput = document.getElementById("resumeUsPlayerTwo");
  const demPlayerOneInput = document.getElementById("resumeDemPlayerOne");
  const demPlayerTwoInput = document.getElementById("resumeDemPlayerTwo");
  const usScoreInput = document.getElementById("resumeUsScore");
  const demScoreInput = document.getElementById("resumeDemScore");

  if (usPlayerOneInput) usPlayerOneInput.value = basePlayers.us[0] || "";
  if (usPlayerTwoInput) usPlayerTwoInput.value = basePlayers.us[1] || "";
  if (demPlayerOneInput) demPlayerOneInput.value = basePlayers.dem[0] || "";
  if (demPlayerTwoInput) demPlayerTwoInput.value = basePlayers.dem[1] || "";
  if (usScoreInput) usScoreInput.value = totals.us;
  if (demScoreInput) demScoreInput.value = totals.dem;

  openModal("resumeGameModal");
}
function closeResumeGameModal() {
  const errorEl = document.getElementById("resumeGameError");
  if (errorEl) {
    errorEl.textContent = "";
    errorEl.classList.add("hidden");
  }
  closeModal("resumeGameModal");
}
function handleResumeGameSubmit(event) {
  event.preventDefault();
  const errorEl = document.getElementById("resumeGameError");
  const showError = (message) => {
    if (errorEl) {
      errorEl.textContent = message;
      errorEl.classList.remove("hidden");
    } else {
      alert(message);
    }
  };

  const usScoreInput = document.getElementById("resumeUsScore");
  const demScoreInput = document.getElementById("resumeDemScore");

  if (!usScoreInput || !demScoreInput) {
    closeResumeGameModal();
    return;
  }

  const usScore = Number(usScoreInput.value);
  const demScore = Number(demScoreInput.value);

  const scoresAreNumbers = Number.isFinite(usScore) && Number.isFinite(demScore);
  if (!scoresAreNumbers) {
    showError("Scores must be numbers.");
    return;
  }

  const withinBounds = Math.abs(usScore) <= 1000 && Math.abs(demScore) <= 1000;
  if (!withinBounds) {
    showError("Scores should stay between -1000 and 1000.");
    return;
  }

  const isMultipleOfFive = (value) => Math.abs(value % 5) < 1e-9;
  if (!isMultipleOfFive(usScore) || !isMultipleOfFive(demScore)) {
    showError("Scores must be in increments of 5.");
    return;
  }

  if (errorEl) {
    errorEl.textContent = "";
    errorEl.classList.add("hidden");
  }

  const usPlayers = ensurePlayersArray([
    sanitizePlayerName(document.getElementById("resumeUsPlayerOne")?.value || ""),
    sanitizePlayerName(document.getElementById("resumeUsPlayerTwo")?.value || ""),
  ]);
  const demPlayers = ensurePlayersArray([
    sanitizePlayerName(document.getElementById("resumeDemPlayerOne")?.value || ""),
    sanitizePlayerName(document.getElementById("resumeDemPlayerTwo")?.value || ""),
  ]);

  const startingTotals = sanitizeTotals({ us: usScore, dem: demScore });
  const updates = {
    rounds: [],
    undoneRounds: [],
    startingTotals,
    gameOver: false,
    winner: null,
    victoryMethod: null,
    lastBidAmount: null,
    lastBidTeam: null,
    biddingTeam: "",
    bidAmount: "",
    showCustomBid: false,
    customBidValue: "",
    enterBidderPoints: false,
    error: "",
    startTime: null,
    accumulatedTime: 0,
    timerLastSavedAt: null,
    pendingPenalty: null,
    savedScoreInputStates: { us: null, dem: null },
  };

  updates.usPlayers = usPlayers;
  updates.demPlayers = demPlayers;

  updateState(updates);
  confettiTriggered = false;
  pendingGameAction = null;
  closeResumeGameModal();
  saveCurrentGameState();
  showSaveIndicator("Starting scores set!");
}

// Ensure resume modal helpers are available to inline handlers
if (typeof window !== "undefined") {
  window.openResumeGameModal = openResumeGameModal;
  window.closeResumeGameModal = closeResumeGameModal;
  window.handleResumeGameSubmit = handleResumeGameSubmit;
}
